[DefaultExecutionOrder(-150)]public sealed class MinefieldRestProbe:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 [RuntimeInitializeOnLoadMethod]static void Boot(){bool run=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsMineRest")>=0;
#if UNITY_EDITOR
 run|=UnityEditor.SessionState.GetBool("LWS.MineRest",false);UnityEditor.SessionState.SetBool("LWS.MineRest",false);
#endif
 if(run){var g=new GameObject("Owned Minefield final-rest physical acceptance");DontDestroyOnLoad(g);if(!SportsProbeInputIsolation.Active)g.AddComponent<SportsProbeInputIsolation>();g.AddComponent<MinefieldRestProbe>();}}
 MinefieldMatch m;Keyboard keyboard;InputSettings.BackgroundBehavior background;string folder,saved,preferenceKey;bool had,restored;int errors;Vector2 command;readonly StringBuilder log=new StringBuilder();
 void Check(bool ok,string label){log.AppendLine((ok?"PASS ":"FAIL ")+label);if(!ok)errors++;File.WriteAllText(folder+"/progress.txt",log.ToString());}
 void Error(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;log.AppendLine("ERROR "+message);File.WriteAllText(folder+"/progress.txt",log.ToString());}}
 void FixedUpdate(){if(m!=null&&m.Live)m.commands[0]=command;}
 IEnumerator Fresh(){m.SetupScreen();for(int i=0;i<8;i++){m.setup.players[i].source=i==0?BowlingSource.Keyboard:BowlingSource.AI;m.setup.players[i].pad=null;}m.weather=1;command=Vector2.zero;Check(m.StartMatch(),"isolated rest fixture starts");Time.timeScale=4;float deadline=Time.realtimeSinceStartup+8;while(m.Phase==MinefieldPhase.Countdown&&Time.realtimeSinceStartup<deadline)yield return null;Check(m.Phase==MinefieldPhase.Driving,"countdown enters actual drive state");for(int i=1;i<8;i++)m.racers[i].Fail();foreach(var h in m.hazards)h.gameObject.SetActive(false);}
 void ControlledLaunch(float z=120){var r=m.racers[0];var p=m.Surface(new Vector3(0,0,z))+Vector3.up*.6f;r.truck.Prepare(p,Quaternion.identity);r.truck.body.linearVelocity=Vector3.forward*10;Check(r.Launch(p),"controlled initialized blast supplies ordinary physical launch");}
 IEnumerator Contact(){float deadline=Time.realtimeSinceStartup+15;while(m.racers[0].FirstContactTime<0&&m.racers[0].Phase==MineAttempt.Launched&&Time.realtimeSinceStartup<deadline)yield return new WaitForFixedUpdate();Check(m.racers[0].FirstContactTime>=0,"actual post-flight terrain contact observed");}
 IEnumerator Settled(){float deadline=Time.realtimeSinceStartup+35;while(m.racers[0].Phase==MineAttempt.Launched&&Time.realtimeSinceStartup<deadline)yield return new WaitForFixedUpdate();Check(m.racers[0].Phase==MineAttempt.Landed&&m.racers[0].LandingLocks==1,"one authoritative final-rest lock after physical resolution");}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("MinefieldRestEvidence");background=InputSystem.settings.backgroundBehavior;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;keyboard=InputSystem.AddDevice<Keyboard>();InputSystem.EnableDevice(keyboard);yield return SportsProbeScene.Ensure<MinefieldMatch>("TruckMinefield");m=FindAnyObjectByType<MinefieldMatch>();yield return null;preferenceKey=m.PreferenceKey;had=SportsPrefs.HasKey(preferenceKey);saved=SportsPrefs.GetString(preferenceKey);Application.logMessageReceived+=Error;
  yield return Fresh();ControlledLaunch();var racer=m.racers[0];Check(!racer.Launch(racer.LaunchOrigin),"same immediate overlapping blast is deduplicated");yield return Contact();float first=racer.truck.body.worldCenterOfMass.z;Check(racer.Distance<0&&racer.LandingLocks==0&&racer.Phase==MineAttempt.Launched,"first contact remains an unresolved physical tumble");float spent=racer.CorrectionSpent;command=Vector2.one;yield return new WaitForSeconds(.4f);Check(!racer.truck.Powered&&racer.CorrectionSpent==spent,"post-contact controls cannot drive or spend new aftertouch");command=Vector2.zero;yield return Settled();Check(!racer.RecoveryLocked&&racer.Distance==MinefieldRules.Precision(racer.LandingOrigin.z),"ordinary supported rest scores CURRENT forward position without recovery");Check(Mathf.Abs(racer.LandingOrigin.z-first)>.5f,"real bounce/slide continues materially beyond first terrain contact");log.AppendLine("PHYSICAL firstContactZ="+first.ToString("F3")+" finalZ="+racer.LandingOrigin.z.ToString("F3")+" contactTime="+racer.FirstContactTime+" finalTime="+racer.LandingTime+" quiet="+racer.QuietTime);File.WriteAllText(folder+"/progress.txt",log.ToString());
  var priorFlag=m.landingFlags[0];var priorPosition=priorFlag.MarkPosition;int priorHeat=m.Heat;typeof(MinefieldMatch).GetMethod("BeginHeat",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(m,null);Check(m.HistoricalFlags.Count>=2&&m.HistoricalFlags[0].Recorded,"prior blast and final-rest flags survive next heat as match history");bool sameFinal=false;foreach(var flag in m.HistoricalFlags){if(flag.HeatMark==priorHeat&&flag.MarkPosition==priorPosition&&flag.MarkText.Contains("FINAL REST"))sameFinal=true;Check(flag.GetComponentsInChildren<Collider>(true).Length==0,"historical waving flag is nonblocking");}Check(sameFinal,"historical final rest retains actual position, heat and participant text");
  yield return Fresh();ControlledLaunch(180);racer=m.racers[0];yield return Contact();first=racer.truck.body.worldCenterOfMass.z;racer.truck.body.linearVelocity=new Vector3(0,1,-6);racer.truck.body.angularVelocity=Vector3.right*1.1f;yield return Settled();Check(racer.LandingOrigin.z<first-1&&racer.Distance==MinefieldRules.Precision(racer.LandingOrigin.z),"controlled backward physical slide lowers score instead of retaining first/furthest contact");log.AppendLine("BACKWARD contactZ="+first+" finalZ="+racer.LandingOrigin.z);
  yield return Fresh();ControlledLaunch(240);racer=m.racers[0];yield return Contact();float firstBlast=racer.LaunchTime;float used=racer.CorrectionSpent;Check(racer.Launch(racer.truck.body.position+Vector3.right*4)&&racer.Launches==2,"a distinct later blast can physically restart the unresolved tumble");Check(m.HistoricalFlags.Count==1&&racer.LaunchTime==firstBlast&&racer.CorrectionSpent==used,"secondary blast preserves first record and correction budget while retaining previous blast flag");yield return null;m.Pause();var pose=racer.truck.body.position;float clock=m.HeatTime;yield return new WaitForSecondsRealtime(.15f);Check(pose==racer.truck.body.position&&clock==m.HeatTime,"normal-frame pause preserves live post-blast pose and resolution clock");m.Resume();Time.timeScale=4;yield return Settled();Check(racer.LandingLocks==1&&!racer.RecoveryLocked,"multiple blasts still finish with one ordinary rest score");
  yield return Fresh();ControlledLaunch(300);racer=m.racers[0];racer.truck.body.useGravity=false;racer.truck.body.position=m.Surface(new Vector3(0,0,300))+Vector3.up*30;racer.truck.body.linearVelocity=racer.truck.body.angularVelocity=Vector3.zero;yield return new WaitForSeconds(1.8f);Check(racer.Distance<0&&racer.QuietTime==0&&racer.Phase==MineAttempt.Launched,"stationary unsupported apex is never accepted as rest");typeof(MinefieldRacer).GetField("flight",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(racer,95f);yield return new WaitForFixedUpdate();yield return new WaitForFixedUpdate();Check(!racer.RecoveryLocked&&racer.LandingLocks==0&&racer.Phase==MineAttempt.Launched&&!racer.truck.body.isKinematic,"unsupported flight beyond ninety seconds stays physical and unresolved");racer.truck.body.useGravity=true;yield return Settled();Check(!racer.RecoveryLocked,"valid long flight subsequently settles normally on real support");yield return Fresh();ControlledLaunch(300);racer=m.racers[0];yield return Contact();racer.truck.body.linearVelocity=new Vector3(.6f,0,.6f);racer.truck.body.angularVelocity=Vector3.up*.6f;typeof(MinefieldRacer).GetField("flight",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(racer,180f);yield return new WaitForFixedUpdate();yield return new WaitForFixedUpdate();Check(racer.RecoveryLocked&&racer.LandingLocks==1,"separate persistent supported low-energy failure has bounded recovery");Check(m.landingFlags[0].MarkText.Contains("RECOVERY LOCK"),"supported fallback is distinguished in final flag presentation");
  m.SetupScreen();Check(m.StartMatch()&&m.HistoricalFlags.Count==0&&m.racers[0].LandingLocks==0,"rematch clears prior-match flag history and resolution state");m.SetupScreen();SportsNavigation.FrontEnd();yield return null;yield return null;Check(FindAnyObjectByType<SportsFrontEnd>()!=null&&FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length==1,"collection return cleans temporary physical state and has one listener");log.AppendLine("ERRORS="+errors+". Actual terrain/PhysX motion with explicitly initialized blast, backward-velocity and timer/support fixtures. No human or hardware acceptance.");File.WriteAllText(folder+"/result.txt",log.ToString());Restore();if(!Application.isEditor)Application.Quit(errors==0?0:2);
 }
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Error;if(m!=null){foreach(var r in m.racers)r.truck.body.useGravity=true;m.SetupScreen();}if(preferenceKey!=null){if(had)SportsPrefs.SetString(preferenceKey,saved);else SportsPrefs.DeleteKey(preferenceKey);SportsPrefs.Save();}if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);keyboard=null;InputSystem.settings.backgroundBehavior=background;Time.timeScale=1;}
 void OnDestroy(){Restore();}
